INSERT INTO public.restaurants(id,status,origin_name,naver_name,approved_name,lat,lng,geocoding_success,jibun_address,categories,tzuyang_review,trace_id,youtube_link,evaluation_results,source_type,created_by,updated_by_admin_id,phone) SELECT id,status,origin_name,naver_name,approved_name,lat,lng,geocoding_success,jibun_address,categories,tzuyang_review,trace_id,youtube_link,evaluation_results,source_type,created_by,updated_by_admin_id,phone FROM jsonb_populate_record(NULL::public.restaurants,'{"id": "de0a3945-3b00-4f98-974c-1e505ef52b0f", "status": "pending", "origin_name": "fixture branch", "naver_name": "fixture branch", "approved_name": "fixture branch", "lat": 37.5, "lng": 127, "geocoding_success": true, "jibun_address": "synthetic business address", "categories": ["\ud55c\uc2dd"], "tzuyang_review": "fixture review", "trace_id": "fd7bb6314e554d2e972dc13cf454ebcc", "youtube_link": "https://www.youtube.com/watch?v=ABCDEFGHIJK", "evaluation_results": {"visit_authenticity": {"eval_value": 1, "eval_basis": "fixture evidence"}, "rb_inference_score": {"eval_value": 1, "eval_basis": "fixture evidence"}, "review_faithfulness_score": {"eval_value": 1, "eval_basis": "fixture evidence"}, "rb_grounding_TF": {"eval_value": true, "eval_basis": "fixture evidence"}, "category_validity_TF": {"eval_value": true, "eval_basis": "fixture evidence"}, "category_TF": {"eval_value": true, "eval_basis": "fixture evidence"}, "location_match_TF": {"origin_name": "fixture branch", "eval_value": true, "match_status": "matched", "evidence_families": ["source_geo", "provider_candidate"]}}, "source_type": "crawler", "created_by": null, "updated_by_admin_id": null, "phone": "02-777-0000"}'::jsonb);INSERT INTO public.restaurants(id,status,origin_name,naver_name,approved_name,lat,lng,geocoding_success,jibun_address,categories,tzuyang_review,trace_id,youtube_link,evaluation_results,source_type,created_by,updated_by_admin_id,phone) SELECT id,status,origin_name,naver_name,approved_name,lat,lng,geocoding_success,jibun_address,categories,tzuyang_review,trace_id,youtube_link,evaluation_results,source_type,created_by,updated_by_admin_id,phone FROM jsonb_populate_record(NULL::public.restaurants,'{"id": "25be49e0-6f70-4c81-a5fa-a86ba31926f5", "status": "approved", "origin_name": "budget fixture branch", "naver_name": "budget fixture branch", "approved_name": "budget fixture branch", "lat": 37.5, "lng": 127, "geocoding_success": true, "jibun_address": "synthetic business address", "categories": ["\ud55c\uc2dd"], "tzuyang_review": "fixture review", "trace_id": "d51ef3fda4aa4bf18c70355dc64970e4", "youtube_link": "https://www.youtube.com/watch?v=QRSTUVWXYZ0", "evaluation_results": {"visit_authenticity": {"eval_value": 1, "eval_basis": "fixture evidence"}, "rb_inference_score": {"eval_value": 1, "eval_basis": "fixture evidence"}, "review_faithfulness_score": {"eval_value": 1, "eval_basis": "fixture evidence"}, "rb_grounding_TF": {"eval_value": true, "eval_basis": "fixture evidence"}, "category_validity_TF": {"eval_value": true, "eval_basis": "fixture evidence"}, "category_TF": {"eval_value": true, "eval_basis": "fixture evidence"}, "location_match_TF": {"origin_name": "fixture branch", "eval_value": true, "match_status": "matched", "evidence_families": ["source_geo", "provider_candidate"]}}, "source_type": "crawler", "created_by": null, "updated_by_admin_id": null, "phone": "02-999-1111"}'::jsonb);INSERT INTO pipeline_control.restaurant_review_policy(singleton,version,enabled,operator_id,batch_size,daily_limit) VALUES(true,7,true,'00000000-0000-0000-0000-000000000065',1,1);SET LOCAL ROLE service_role;SELECT set_config('request.jwt.claim.role','',true);SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);DO $test$ DECLARE a jsonb;b jsonb;item jsonb;readback jsonb;token uuid:=gen_random_uuid();request uuid:=gen_random_uuid();judgment jsonb;current_fp text;BEGIN a:=public.restaurant_review_automation_tick(gen_random_uuid());IF (a->>'recheck')::int<>1 OR (a->>'scanned')::int<>1 THEN RAISE EXCEPTION 'REVIEW_FIX_INITIAL_ONE_BATCH';END IF;item:=public.restaurant_review_automation_worker('claim',NULL,token,'{}');IF item->>'id' IS NULL OR public.restaurant_review_automation_worker('claim',NULL,gen_random_uuid(),'{}') IS NOT NULL THEN RAISE EXCEPTION 'REVIEW_FIX_ONE_CLAIM';END IF;INSERT INTO pipeline_control.restaurant_review_items(run_id,restaurant_id,fingerprint,decision,reason,state,finished_at) SELECT run_id,'25be49e0-6f70-4c81-a5fa-a86ba31926f5',repeat('c',64),'approve','synthetic already consumed daily budget','applied',now() FROM pipeline_control.restaurant_review_items WHERE id=(item->>'id')::uuid;judgment:=jsonb_build_object('schemaVersion',1,'model','gemini-3.8-flash','modelVersion','gemini-3.8-flash','promptVersion','restaurant-review-v1','inputSha256',item#>>'{decisionContext,inputSha256}','promptSha256',repeat('a',64),'recommendation','approve','evidenceCodes',jsonb_build_array('visit_supported','identity_supported','review_grounded','category_supported','location_corroborated','source_consistent'));IF NOT pipeline_control.restaurant_review_gemini_valid(judgment,item#>>'{decisionContext,inputSha256}') THEN RAISE EXCEPTION 'REVIEW_FIX_JUDGMENT_SHAPE';END IF;a:=public.restaurant_review_automation_worker('complete',(item->>'id')::uuid,token,jsonb_build_object('evaluation_results','{"visit_authenticity": {"eval_value": 1, "eval_basis": "synthetic revised completed evidence"}, "rb_inference_score": {"eval_value": 1, "eval_basis": "fixture evidence"}, "review_faithfulness_score": {"eval_value": 1, "eval_basis": "fixture evidence"}, "rb_grounding_TF": {"eval_value": true, "eval_basis": "fixture evidence"}, "category_validity_TF": {"eval_value": true, "eval_basis": "fixture evidence"}, "category_TF": {"eval_value": true, "eval_basis": "fixture evidence"}, "location_match_TF": {"origin_name": "fixture branch", "eval_value": true, "match_status": "matched", "evidence_families": ["source_geo", "provider_candidate"]}}'::jsonb,'gemini_decision',judgment));IF a#>>'{geminiDecision,outcome}'<>'deferred' OR NOT EXISTS(SELECT 1 FROM pipeline_control.restaurant_review_items WHERE id=(item->>'id')::uuid AND state='succeeded' AND reason='daily_limit' AND fingerprint<>applied_fingerprint) THEN RAISE EXCEPTION 'REVIEW_FIX_CONFIRMED_DEFERRED';END IF;SELECT pipeline_control.restaurant_review_fingerprint(to_jsonb(t)) INTO current_fp FROM public.restaurants t WHERE id='de0a3945-3b00-4f98-974c-1e505ef52b0f';INSERT INTO public.restaurants(id,status,origin_name,naver_name,approved_name,lat,lng,geocoding_success,jibun_address,categories,tzuyang_review,trace_id,youtube_link,evaluation_results,source_type,created_by,updated_by_admin_id,phone) SELECT id,status,origin_name,naver_name,approved_name,lat,lng,geocoding_success,jibun_address,categories,tzuyang_review,trace_id,youtube_link,evaluation_results,source_type,created_by,updated_by_admin_id,phone FROM jsonb_populate_record(NULL::public.restaurants,'{"id": "ff1d7aed-96c5-4be5-908e-c62cbfa72031", "status": "approved", "origin_name": "duplicate fixture branch", "naver_name": "duplicate fixture branch", "approved_name": "duplicate fixture branch", "lat": 37.5, "lng": 127, "geocoding_success": true, "jibun_address": "synthetic business address", "categories": ["\ud55c\uc2dd"], "tzuyang_review": "fixture review", "trace_id": "cf7a9248ee744fc0a9acdd4e3fb8a12b", "youtube_link": "https://www.youtube.com/watch?v=LMNOPQRSTUV", "evaluation_results": {"visit_authenticity": {"eval_value": 1, "eval_basis": "fixture evidence"}, "rb_inference_score": {"eval_value": 1, "eval_basis": "fixture evidence"}, "review_faithfulness_score": {"eval_value": 1, "eval_basis": "fixture evidence"}, "rb_grounding_TF": {"eval_value": true, "eval_basis": "fixture evidence"}, "category_validity_TF": {"eval_value": true, "eval_basis": "fixture evidence"}, "category_TF": {"eval_value": true, "eval_basis": "fixture evidence"}, "location_match_TF": {"origin_name": "fixture branch", "eval_value": true, "match_status": "matched", "evidence_families": ["source_geo", "provider_candidate"]}}, "source_type": "crawler", "created_by": null, "updated_by_admin_id": null, "phone": "02-777-0000"}'::jsonb);IF pipeline_control.restaurant_review_fingerprint((SELECT to_jsonb(t) FROM public.restaurants t WHERE id='de0a3945-3b00-4f98-974c-1e505ef52b0f'))<>current_fp OR pipeline_control.restaurant_review_decision((SELECT to_jsonb(t) FROM public.restaurants t WHERE id='de0a3945-3b00-4f98-974c-1e505ef52b0f'))<>'hold:duplicate_requires_review' THEN RAISE EXCEPTION 'REVIEW_FIX_CHANGED_CLASSIFICATION_ONLY';END IF;a:=public.restaurant_review_automation_tick(request);IF (a->>'held')::int<>1 OR (a->>'scanned')::int<>1 OR (SELECT status FROM public.restaurants WHERE id='de0a3945-3b00-4f98-974c-1e505ef52b0f')<>'hold' THEN RAISE EXCEPTION 'REVIEW_FIX_CHANGED_DEFERRED_SKIPPED';END IF;readback:=public.restaurant_review_automation_worker('read',(item->>'id')::uuid,token,NULL);IF readback->>'state'<>'applied' OR readback->>'reason'<>'duplicate_requires_review' OR readback#>>'{geminiDecision,outcome}'<>'hold' THEN RAISE EXCEPTION 'REVIEW_FIX_DEFERRED_READBACK';END IF;b:=public.restaurant_review_automation_tick(request);IF a IS DISTINCT FROM b THEN RAISE EXCEPTION 'REVIEW_FIX_REQUEST_IDEMPOTENCY';END IF;b:=public.restaurant_review_automation_tick(gen_random_uuid());IF (b->>'scanned')::int<>0 OR public.restaurant_review_automation_worker('claim',NULL,gen_random_uuid(),'{}') IS NOT NULL THEN RAISE EXCEPTION 'REVIEW_FIX_DEFERRED_SECOND_BATCH';END IF;IF public.restaurant_review_automation_status()#>>'{judgmentEngine,maxCallsPerClaim}'<>'1' THEN RAISE EXCEPTION 'REVIEW_FIX_MODEL_CAP_CHANGED';END IF;END $test$;ROLLBACK;